"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[630],{1405(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});const o=JSON.parse('{"id":"basic/getting-started/history","title":"History","description":"At the time of the formation of the Waitemata Lodge, the only Masonic Lodge in Auckland was the Ara Lodge, No. 348 in the Irish Constitution. A petition, signed by six brothers, was sent to the Provincial Grand Lodge of New South Wales asking for dispensation to start this Lodge. The Petition was granted and the first meeting of the Lodge was held on 6 September 1855 when W. Bro. Buchanan, W. Master of Ara Lodge No. 348 IC installed Sir Samuel Osborne-Gibbes as Master of Waitemata Lodge.","source":"@site/../docs/basic/getting-started/history.md","sourceDirName":"basic/getting-started","slug":"/basic/getting-started/history","permalink":"/docs/basic/getting-started/history","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"history","title":"History"},"sidebar":"sidebar","next":{"title":"Meetings","permalink":"/docs/basic/getting-started/meetings"}}');var a=n(4848),r=n(8453);const i={id:"history",title:"History"},s=void 0,h={},d=[];function l(e){const t={p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"At the time of the formation of the Waitemata Lodge, the only Masonic Lodge in Auckland was the Ara Lodge, No. 348 in the Irish Constitution. A petition, signed by six brothers, was sent to the Provincial Grand Lodge of New South Wales asking for dispensation to start this Lodge. The Petition was granted and the first meeting of the Lodge was held on 6 September 1855 when W. Bro. Buchanan, W. Master of Ara Lodge No. 348 IC installed Sir Samuel Osborne-Gibbes as Master of Waitemata Lodge."}),"\n",(0,a.jsx)("summary",{children:"It was not until 3rd December 1856 that Waitemata received its own Grand Lodge Warrant, which carried the number 990. This remained our number until 1863 when  the following letter was received from Grand Lodge."}),"\n",(0,a.jsx)("img",{src:"/img/b-tools.jpg",alt:"B tools"}),"\n",(0,a.jsx)(t.p,{children:"That the Grand Lodge having resolved that the number of new Lodges on the Register shall be brought forward in regular succession by filling up those numbers which have become vacant either by the voluntary surrender of Warrants or by erasure of Lodges. I have the honour to inform you that your Lodge which has hitherto been known and distinguished as No.990 will henceforth stand on the Register of Grand Lodge as No. 689 and the latter number you are to refer to in all returns and communications addressed to the Grand Lodge."}),"\n",(0,a.jsx)("b",{children:"By Order Wm. Gray Clark. G. Sec."}),"\n",(0,a.jsx)(t.p,{children:"In 1903 the Lodge wrote to Grand Lodge asking if the number on our Warrant should be changed to 689 and received the following reply:"}),"\n",(0,a.jsx)(t.p,{children:"In answer to your letter of the 20th regarding the Warrant of your Lodge it is in the same condition as all the others that were established before 1863. It is not necessary to have the new number placed on the Warrant but if it is desired the Warrant may be returned for endorsement but as such endorsement is usually made on the back it would not be of service if the Warrant is to be framed. Moreover the Lodge will be unable to meet in the absence of the Warrant."}),"\n",(0,a.jsx)("b",{children:"Letchworth. Grand Sec."}),"\n",(0,a.jsx)("img",{src:"/img/square-compasses.jpg",alt:"square compasses"}),"\n",(0,a.jsx)(t.p,{children:"Needless to say the Warrant was never endorsed and still shows the number 990.\nSuffice it to say that the early years of the Lodge were on numerous occasions very stormy.\nWe have on record that on two occasions peace was only restored after communications from Grand Lodge and the minutes show that several times the Lodge was closed in due form and not in peace, love and harmony. Perhaps these stormy years were to be expected as when the Lodge received its Warrant it also had a letter from Grand Lodge stating that a copy of the Book of Constitutions could not be spared for Auckland. It is possible that the strength of independence that was necessary to become successful pioneers did not always lead to peaceful Lodge meetings, but following truly Masonic teachings these disturbances were always settled in the end. The Brethren concerned once again sat in open Lodge and worked with that love and harmony which should at all times characterise Freemasons."}),"\n",(0,a.jsx)(t.p,{children:"The population of Auckland during the early years of Waitemata\u2019s existence was of an essentially floating nature and this reflected itself to a large extent in the Lodge; many of our early brethren were members of Naval or Merchant ships or served in the regiments of the regular British Army based in New Zealand to assist in the early settlement and many took part in the Land Wars in the area. This led to a fluctuating work load in the Lodge and we note that in the years 1860 to 1867 the Lodge admitted 205 members, 81 joining and 124 initiates. This caused as many as 20 emergency meetings to be worked in a year and it was common to work two different degrees at one meeting, many of these meetings not finishing until 11pm. This heavy workload must have been very tiring as we find record of a notice of motion put to the Lodge that no degree be started after 9.30pm."}),"\n",(0,a.jsx)(t.p,{children:"It was inevitable that as Auckland grew more Lodges would be required and despite the fact that some of the Brethren wished for Waitemata to remain the only English Lodge, the majority supported the Petition for a new Lodge. This being successful, the Prince of Wales Lodge had its first meeting on 28th September 1871. Once again, we find records of several stormy years, which continued until Grand Lodge wrote and asked that Masonic relationships be re-established between the Brethren concerned. From then on Masonry in the Auckland Province took a new lease of life and on 17th July 1878 the second daughter Lodge, The Eden Lodge, had its first meeting. The Minutes show that the Waitemata Lodge presented their spare Bible to Eden Lodge with their best wishes. This should dispel the rumours of many years standing that they came by it dishonestly!"}),"\n",(0,a.jsx)(t.p,{children:"During the following 10 years or so, Waitemata either assisted or signed the petition for several new Lodges"}),"\n",(0,a.jsx)(t.p,{children:"The Eden Lodge, No. 1530 \u2013 1875\nThe Star of the North Lodge No. 1647 \u2013 27th September 1876\nRemuera Lodge No. 1710 \u2013 28th February 1877\nSt George Lodge No. 1801 \u2013 3rd November 1877\nNorthern Light Lodge No. 1878 \u2013 1880\nDuke of Albany Lodge No. 2073 \u2013 2nd September 1884\nFranklin Lodge No. 2138 \u2013 1885\nLodge of Harmony No. 2180 \u2013 26th May1886\nWaitemata was connected with nearly all the English Lodges in the Auckland Province, a sure indication of the firm Masonic roots our early brethren planted back in 1855."}),"\n",(0,a.jsx)(t.p,{children:"Before we leave those early years let me repeat a passage in the Centennial History:"}),"\n",(0,a.jsx)(t.p,{children:"It is not necessary to do a pen picture of conditions pertaining at that time in Auckland, with its ill-formed streets, poor lighting, and lack of transport facilities, to visualize the discomfort and self-sacrifice which had to be borne by the brethren in attending the regular meetings. They showed a zeal worthy of the true spirit of the Pioneers. Let us honour them in the first pages of this History by acknowledging our indebtedness to them for their love and loyalty. By their devotion and determination they have established a strong and virile influence on Freemasonry in the Auckland District."}),"\n",(0,a.jsx)(t.p,{children:"Lodge Meeting Place\nFor the first three years, with a few exceptions, the meetings were held in the William Denny Hotel on the corner of Queen and Swanson Streets. For the next 23 years the meetings were held in the Masonic Hotel, Princes Street, on the site subsequently occupied by the Grand Hotel."}),"\n",(0,a.jsx)(t.p,{children:"The Waitemata Lodge then became shareholders with other Lodges, who built the Masonic Hall next door to the Masonic Hotel in Princes Street. Here the first meeting of the Lodge was held on 12th December 1881."}),"\n",(0,a.jsx)(t.p,{children:"In 1974 it became obvious that a considerable amount of money would be needed for structural repairs and general refurbishing and, as the parking had become extremely difficult since the building of the Hotel Intercontinental opposite, it was decided by all the Lodges holding shares to sell the building. The last meeting of the Lodge there was held on 21st July 1975. It was with a great deal of sorrow that Waitemata left the hall that they had called home for 94 years."}),"\n",(0,a.jsx)(t.p,{children:"In June of 1975 Waitemata accepted the offer from the Lodge of Harmony to use the Lodge rooms at Princes Street, Otahuhu, and held our first meeting here in August of that year."}),"\n",(0,a.jsx)(t.p,{children:"In 1989 the Waitemata Lodge was invited to purchase a one-quarter share in the Herne Bay Lodge room, in Argyle Street in Herne bay. The invitation was accepted and in 1990 the Waitemata Lodge started meeting in Herne bay. The Lodge continued to meet very happily there until the merging of The United Services Lodge and The Herne bay Lodge led to a situation where the Herne Bay Lodge and the Ponsonby Lodge no. 54 could no longer maintain their share of the outgoings and decided to move to the new Masonic Centre for the New Zealand Constitution at Khyber Pass. This made it necessary to sell the building in Herne Bay. The Waitemata Lodge moved to the English Masonic Centre at Ellerslie and changing our meeting night from the third Monday to the first Wednesday."}),"\n",(0,a.jsx)(t.p,{children:"After two interim meetings in October and November 2010 which were held in the Eden Lodge Rooms, the Waitemata Lodge commenced meeting in the Ellerslie Masonic Centre on the first Wednesday of February 2011. At the same time, we became a Dining Lodge, enjoying a full dinner after our ceremonies, with no charge to any visitors \u2013 and starting at the earlier time of 6.30pm. At the same time, our Installation Meeting was moved from May to June. A small change was subsequently made to our schedule, so that we now meet from March to December rather than February to November."}),"\n",(0,a.jsx)(t.p,{children:"The Lodge and The Grand Lodge of New Zealand\nTowards the end of the nineteenth century, there was a very understandable movement to establish an autonomous Grand Lodge of New Zealand. After discussion and negotiation with the English, Irish and Scottish Constitutions, this came about in 1890."}),"\n",(0,a.jsx)(t.p,{children:"Some Lodges, however, did not join the new Constitution, adhered to their original loyalties. The 23 English Lodges in the North Island have persisted to the present day and coexist happily with each other and the New Zealand Constitution Lodges. The difference in uniform, attitudes and the conduct of ceremonies provides a source of interest and comparison that would be lacking if there were only one constitution."}),"\n",(0,a.jsx)(t.p,{children:"The Ara Lodge No. 348 IC\nSesquicentenary Celebrations"})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>s});var o=n(6540);const a={},r=o.createContext(a);function i(e){const t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);